//! Independent venue-agent fixture e08fca01bb; expected bytes are never generated by Rust.
use safe_cex_crypto::lighter::{
    SchnorrNonce, poseidon2_hash, poseidon2_hash_fp5, poseidon2_two_to_one, public_key,
    schnorr_sign, schnorr_verify,
};
use serde_json::Value;
use sha2::{Digest, Sha256};
use std::{collections::BTreeMap, path::Path};
#[path = "support/lighter_source_pin.rs"]
mod source_pin;
const FIXTURE: &str = include_str!("fixtures/lighter/venue-signing-preimages.json");
fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}
fn decode(text: &str) -> Vec<u8> {
    assert!(text.len().is_multiple_of(2));
    text.as_bytes()
        .as_chunks::<2>()
        .0
        .iter()
        .map(|pair| u8::from_str_radix(std::str::from_utf8(pair).unwrap(), 16).unwrap())
        .collect()
}
#[test]
fn independent_venue_artifact_and_sources_are_pinned() {
    assert_eq!(
        hex(&Sha256::digest(FIXTURE.as_bytes())),
        "afe399cc424ff3e4e5393ef9c2f8f642b770530328f6cc70d6aefd830383679a",
        "independent fixture bytes changed"
    );
    let corpus: Value = serde_json::from_str(FIXTURE).unwrap();
    assert_eq!(corpus["versions"]["lighter-sdk"], "0.0.1");
    assert_eq!(corpus["versions"]["poseidon-crypto"], "0.0.1");
    assert_eq!(
        corpus["sources"]["packages/poseidon-crypto/src/wasm/poseidon_crypto.wasm"],
        "4fcb6e608498ddf223ee9d0fadb00ab8dd3736f985ab37eec22a195588a029c3"
    );
    let pins: Value = serde_json::from_str(include_str!(
        "fixtures/lighter/reviewed-source-provenance.json"
    ))
    .unwrap();
    for (file, pin) in pins.as_object().unwrap() {
        assert_eq!(
            corpus["sources"][file], pin["originalSha256"],
            "reviewed provenance must name the original source: {file}"
        );
    }
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
    for (file, digest) in corpus["sources"].as_object().unwrap() {
        if pins
            .get(file)
            .is_some_and(|pin| pin.get("declarationsSha256").is_some())
        {
            source_pin::verify(file, None);
            continue;
        }
        let expected = pins.get(file).map_or(digest, |pin| &pin["currentSha256"]);
        assert_eq!(
            hex(&Sha256::digest(std::fs::read(root.join(file)).unwrap())),
            expected.as_str().unwrap(),
            "independent source drift: {file}"
        );
    }
}
#[test]
fn reviewed_shared_declarations_admit_unrelated_types_and_reject_each_mutation() {
    let result = source_pin::run("lighter-source-provenance-controls.cjs", &[]);
    assert_eq!(result["unrelatedTypeEditsAccepted"], 2);
    assert_eq!(
        result["namedMutationFailures"],
        serde_json::json!([
            "OrderSide",
            "OrderStatus",
            "OrderStopTriggerType",
            "OrderTimeInForce",
            "OrderType"
        ])
    );
    assert_eq!(result["missingPinRejected"], true);
    assert_eq!(result["missingDeclarationRejected"], true);
    assert_eq!(result["missingCapturedSourceRejected"], true);
}
#[test]
fn every_independent_wasm_hash_and_signature_matches_rust() {
    let corpus: Value = serde_json::from_str(FIXTURE).unwrap();
    let key = decode(corpus["secret"].as_str().unwrap());
    let pk = public_key(&key).unwrap();
    assert_eq!(pk.as_slice(), decode(corpus["publicKey"].as_str().unwrap()));
    assert_eq!(corpus["entropyByte"], 66);
    let mut calls = BTreeMap::<String, usize>::new();
    let mut profiles = BTreeMap::<String, usize>::new();
    for case in corpus["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let profile = name.split('/').take(2).collect::<Vec<_>>().join("/");
        *profiles.entry(profile).or_default() += 1;
        for call in case["crypto"].as_array().unwrap() {
            let method = call["method"].as_str().unwrap();
            *calls.entry(method.into()).or_default() += 1;
            let input = decode(call["inputs"][0].as_str().unwrap());
            let expected = call["result"].as_str().unwrap();
            let result = match method {
                "poseidon2Hash" => poseidon2_hash(&input).unwrap().to_vec(),
                "poseidon2HashFp5" => poseidon2_hash_fp5(&input).unwrap().to_vec(),
                "poseidon2HashTwoToOne" => {
                    poseidon2_two_to_one(&input, &decode(call["inputs"][1].as_str().unwrap()))
                        .unwrap()
                        .to_vec()
                }
                "schnorrSign" => {
                    // Offline fixture ONLY: Go rand.Int's big-endian 0x42 bytes are symmetric and canonical.
                    let nonce = SchnorrNonce::from_bytes(&[66; 40]).unwrap();
                    let signature = schnorr_sign(&input, &key, nonce).unwrap();
                    assert!(
                        schnorr_verify(&input, &pk, &decode(expected)).unwrap(),
                        "independent signature verification: {name}"
                    );
                    signature.to_vec()
                }
                other => panic!("uncompared independent WASM method: {other}"),
            };
            assert_eq!(
                result,
                decode(expected),
                "independent WASM mismatch: {name}/{method}"
            );
        }
    }
    assert_eq!(
        calls,
        BTreeMap::from([
            ("poseidon2Hash".into(), 100),
            ("poseidon2HashFp5".into(), 60),
            ("poseidon2HashTwoToOne".into(), 16),
            ("schnorrSign".into(), 92)
        ])
    );
    assert_eq!(
        profiles,
        BTreeMap::from([
            ("lighter/livenet".into(), 23),
            ("lighter/testnet".into(), 23),
            ("lighter-robinhood/livenet".into(), 23),
            ("lighter-robinhood/testnet".into(), 23)
        ])
    );
}
